const RUNTIMES = { "Python": LOGOS.python, "PHP": LOGOS.php, "Ruby": LOGOS.ruby, "Bash": LOGOS.bash, "Shell": LOGOS.bash, "Node.js": LOGOS.nodejs, "Deno": LOGOS.denojs, "Bun": LOGOS.bun, "Go": LOGOS.go, "Rust": LOGOS.rust, "Perl": LOGOS.perl, "Java": LOGOS.java, ".NET": LOGOS.dotnetcore, "Elixir": LOGOS.elixir, "Dart": LOGOS.dart, "Kotlin": LOGOS.kotlin, "Lua": LOGOS.lua, "PowerShell": LOGOS.powershell };

const urls = new Map();
// runtimeIcon returns a data URL for the logo of the row's language, or "".
export function runtimeIcon(row) {
  const svg = RUNTIMES[row.language];
  if (!svg) return "";
  if (!urls.has(row.language)) urls.set(row.language, "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg));
  return urls.get(row.language);
}
